  if (!(target instanceof Element)) {
    return false;
  }

  if (
    target.closest(
      [
        "input",
        "textarea",
        "select",
        '[contenteditable="true"]',
        '[role="slider"]',
        '[data-sidebar="panel"]',
        '[data-sidebar="trigger"]',
        "[data-vaul-drawer]",
        "[data-vaul-no-drag]",
        "[data-no-sidebar-swipe]",
      ].join(", "),
    ) !== null
