      className={cn(COARSE_POINTER_HEADER_ICON_BUTTON_CLASS, className)}
      aria-expanded={ariaExpanded ?? (isCompactViewport ? openMobile : open)}
      onClick={(event) => {
        onClick?.(event);
        toggleSidebar();
      }}
