    const content: PaneContent = {
      kind: "plugin-panel",
      pluginId: "automations",
      panelPath: "automations",
      subPath: "proj_personal/weekly-review",
    };
    const store = renderSplitArea({
      path: "/plugins/automations/automations/proj_personal/weekly-review",
      layout: {
        root: { type: "pane", paneId: "pane-automation", content },
        focusedPaneId: "pane-automation",
      },
      routeContent: content,
    });

    const breadcrumb = await screen.findByRole("navigation", {
      name: "Breadcrumb",
    });
    expect(breadcrumb.textContent).toContain("Automations");
    expect(breadcrumb.textContent).toContain("Installed");
    expect(breadcrumb.textContent).toContain("weekly-review");

    store.set(resourceRouteLabelAtom, "Weekly review");
    await waitFor(() =>
      expect(breadcrumb.textContent).toContain("Weekly review"),
    );

    fireEvent.click(screen.getByRole("link", { name: "Installed" }));
    expect(screen.getByTestId("location").textContent).toBe(
      "/plugins/automations/automations",
    );
  });

  it("ignores a layout written by another tab (issue #873)", async () => {
    renderSplitArea({ path: threadPath("thr-a") });
    expect(await screen.findByTestId("pane-thr-a")).toBeTruthy();

    // Another tab selects thr-b: same-origin localStorage write plus the
    // `storage` event the browser delivers to every other tab.
    const otherTabLayout = serializeSplitLayout({
      root: { type: "pane", paneId: "pane-1", content: threadContent("thr-b") },
      focusedPaneId: "pane-1",
    });
    window.localStorage.setItem(SPLIT_LAYOUT_STORAGE_KEY, otherTabLayout);
    fireEvent(
      window,
      new StorageEvent("storage", {
        key: SPLIT_LAYOUT_STORAGE_KEY,
        newValue: otherTabLayout,
        storageArea: window.localStorage,
      }),
    );

    // This tab keeps its own thread and URL; nothing bleeds across tabs.
    await waitFor(() => {
      expect(screen.getByTestId("location").textContent).toBe(
        threadPath("thr-a"),
      );
    });
    expect(screen.queryAllByTestId(/^pane-/)).toHaveLength(1);
    expect(screen.getByTestId("pane-thr-a")).toBeTruthy();
    expect(screen.queryByTestId("pane-thr-b")).toBeNull();
  });

  it("falls back to a single pane from the route when persisted state is malformed", async () => {
    window.localStorage.setItem(SPLIT_LAYOUT_STORAGE_KEY, "not json");
    renderSplitArea({ path: threadPath("thr-a") });

    expect(await screen.findByTestId("pane-thr-a")).toBeTruthy();
    // Only the route thread renders — no stale panes leak in.
    expect(screen.queryAllByTestId(/^pane-/)).toHaveLength(1);
    expect(screen.queryByTestId("close-thr-a")).toBeNull();
  });

  it("moves the URL to the surviving pane when the focused pane is closed", async () => {
    renderSplitArea({
      path: threadPath("thr-b"),
      layout: twoPaneLayout("pane-2"),
    });
    await screen.findByTestId("pane-thr-b");

    fireEvent.click(screen.getByTestId("close-thr-b"));

    await waitFor(() => {
      expect(screen.getByTestId("location").textContent).toBe(
        threadPath("thr-a"),
      );
    });
    expect(screen.getByTestId("pane-thr-a")).toBeTruthy();
    expect(screen.queryByTestId("pane-thr-b")).toBeNull();
  });

  it("prunes a stale (archived) pane from a restored split", async () => {
    threadStore.set("thr-b", { archivedAt: 123, deletedAt: null });
    renderSplitArea({
      path: threadPath("thr-a"),
      layout: twoPaneLayout("pane-1"),
    });

    // thr-b is archived, so its pane is pruned; the valid focused pane remains.
    await waitFor(() => {
      expect(screen.queryByTestId("pane-thr-b")).toBeNull();
    });
    expect(screen.getByTestId("pane-thr-a")).toBeTruthy();
    expect(screen.getByTestId("location").textContent).toBe(
      threadPath("thr-a"),
    );
  });

  describe("standalone compact Command Center commit", () => {
    const commandCenterState = createCommandCenterNavigation({
      returnPath: threadPath("thr-b"),
      returnPaneId: "pane-2",
    });

    // The capability reads the real display-mode query, so drive that query
    // rather than stubbing the capability out — the gate is the thing under
    // test here.
    function stubStandaloneDisplayMode(isStandalone: boolean) {
      vi.stubGlobal("matchMedia", (query: string) => ({
        matches: isStandalone && query === STANDALONE_DISPLAY_MODE_QUERY,
        media: query,
        onchange: null,
        addListener: () => {},
        removeListener: () => {},
        addEventListener: () => {},
        removeEventListener: () => {},
        dispatchEvent: () => false,
      }));
    }

    function storedLayout(store: ReturnType<typeof createStore>): SplitLayout {
      const layout = store.get(splitLayoutAtom);
      if (layout === null) {
        throw new Error("Expected a stored split layout");
      }
      return layout;
    }

    function paneContents(store: ReturnType<typeof createStore>) {
      return listPanes(storedLayout(store).root).map((pane) => pane.content);
    }

    beforeEach(() => {
      viewportState.compact = true;
    });

    afterEach(() => {
      vi.unstubAllGlobals();
    });

    it("preserves every pane, its content, and focus", async () => {
      stubStandaloneDisplayMode(true);
      const store = renderSplitArea({
        path: "/",
        layout: twoPaneLayout("pane-2"),
        routeContent: newThreadContent,
        locationState: commandCenterState,
      });

      expect(await screen.findByTestId("root-compose-view")).toBeTruthy();
      expect(paneContents(store)).toEqual([
        threadContent("thr-a"),
        threadContent("thr-b"),
      ]);
      expect(storedLayout(store).focusedPaneId).toBe("pane-2");
    });

    it("still reconciles the same route in a compact browser tab", async () => {
      stubStandaloneDisplayMode(false);
      const store = renderSplitArea({
        path: "/",
        layout: twoPaneLayout("pane-2"),
        routeContent: newThreadContent,
        locationState: commandCenterState,
      });

      // Today's policy: `/` replaces the focused pane's content in place.
      await waitFor(() => {
        expect(paneContents(store)).toEqual([
          threadContent("thr-a"),
          newThreadContent,
        ]);
      });
      expect(storedLayout(store).focusedPaneId).toBe("pane-2");
    });

    it("ignores unvalidated history state in the installed app", async () => {
      stubStandaloneDisplayMode(true);
      const store = renderSplitArea({
        path: "/",
        layout: twoPaneLayout("pane-2"),
        routeContent: newThreadContent,
        locationState: { kind: "some-other-intent", returnPath: "/" },
      });

      await waitFor(() => {
        expect(paneContents(store)).toEqual([
          threadContent("thr-a"),
          newThreadContent,
        ]);
      });
    });
  });

  it("prunes a stale focused pane and moves focus + URL to the survivor", async () => {
    threadStore.set("thr-b", { archivedAt: null, deletedAt: 456 });
    renderSplitArea({
      path: threadPath("thr-b"),
      layout: twoPaneLayout("pane-2"),
    });

    await waitFor(() => {
      expect(screen.queryByTestId("pane-thr-b")).toBeNull();
    });
    expect(screen.getByTestId("pane-thr-a")).toBeTruthy();
    await waitFor(() => {
      expect(screen.getByTestId("location").textContent).toBe(
        threadPath("thr-a"),
      );
    });
  });
});

