  }
  const standaloneSurface = (
    <StandalonePaneContent content={currentContent} />
  );
  // Plugin panels keep their compact header in the shared AppLayout chrome,
  // which the host cannot move with the body, so they sit this gesture out
  // (both as a source and as a destination) until that chrome moves into the
  // page surface.
  if (
    !isStandaloneCompactPwa ||
    layout === null ||
    currentContent.kind === "plugin-panel"
  ) {
    return standaloneSurface;
  }
  return (
    <CompactWorkspaceSwipeHost
      panes={panes.filter((pane) => pane.content.kind !== "plugin-panel")}
      focusedPaneId={layout.focusedPaneId}
      // Already on the Command Center: offer the return, not another open.
      allowsCommandCenter={
        currentContent.kind !== "new-thread" &&
        commandCenterNavigation === null
      }
      returnPaneId={
        currentContent.kind === "new-thread" &&
        commandCenterNavigation !== null
          ? commandCenterNavigation.returnPaneId
          : null
      }
      onFocusPane={focusPane}
      onOpenCommandCenter={openCommandCenterFromSwipe}
      onReturnFromCommandCenter={returnFromCommandCenter}
    >
      {standaloneSurface}
    </CompactWorkspaceSwipeHost>
  );
}

const commandHandlers = (
  <SplitPaneCommandHandlers
    closePane={closePane}
    focusPane={focusPane}
    isSplitActive={isSplitActive}
    layout={layout}
    maximizedPaneId={effectiveMaximizedPaneId}
    panes={panes}
    toggleMaximizePane={toggleMaximizePane}
  />
);

