    layout === null ||
    currentContent.kind === "plugin-panel"
  ) {
    return standaloneSurface;
  }
  return (
    <CompactWorkspaceSwipeHost
      panes={panes.filter((pane) => pane.content.kind !== "plugin-panel")}
      focusedPaneId={layout.focusedPaneId}
      // Already on the Command Center: offer the return, not another open.
      allowsCommandCenter={
        currentContent.kind !== "new-thread" &&
        commandCenterNavigation === null
      }
      returnPaneId={
        currentContent.kind === "new-thread" &&
        commandCenterNavigation !== null
          ? commandCenterNavigation.returnPaneId
          : null
      }
      onFocusPane={focusPane}
      onOpenCommandCenter={openCommandCenterFromSwipe}
      onReturnFromCommandCenter={returnFromCommandCenter}
    >
      {standaloneSurface}
    </CompactWorkspaceSwipeHost>
  );
}

