      !threadSplitsEnabled ||
      currentContent === null ||
      preservesCommandCenterLayout
    ) {
      return;
    }
    setLayout((previous) =>
      reconcileLayoutForContent(previous, currentContent),
    );
  }, [
    currentContent,
    preservesCommandCenterLayout,
    setLayout,
    threadSplitsEnabled,
  ]);

