  }, [navigate, store]);

  const returnFromCommandCenter = useCallback(() => {
    // The entry under this one is the surface the gesture left, so pop it.
    navigate(-1);
  }, [navigate]);

  const closePane = useCallback(
    (paneId: string) => {
      if (layout === null) {
        return;
      }
      const next = removePane(layout, paneId);
